import java.util.Scanner; public class Main { public static void main(String[] args) { Scanner sc = new Scanner(System.in); if (sc.hasNext()) { String s = sc.next(); StringBuilder sb = new StringBuilder(); for (int i = 0; i < s.length(); i++) { char c = s.charAt(i); if (Character.isUpperCase(c)) { sb.append(Character.toLowerCase(c)); } else if (Character.isLowerCase(c)) { sb.append(Character.toUpperCase(c)); } else { sb.append(c); } } System.out.println(sb.toString()); } sc.close(); } }